  ('alola', '알로라도감', 'Alola Pokédex')
insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 19, 10193, false, '2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.', 'Will chew on anything with its fangs. If you see one, you can be certain that 40 more live in the area.'),
  ('national', 20, 10194, false, '뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.', 'Its hind feet are webbed. They act as flippers, so it can swim in rivers and hunt for prey.'),
  ('national', 25, 10196, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10197, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10198, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10199, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10200, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10201, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10267, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 26, 10202, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('national', 27, 10203, false, '땅을 파서 굴을 만든다. 땅속의 단단한 바위도 날카로운 발톱으로 부수며 파고들어 간다.', 'It burrows into the ground to create its nest. If hard stones impede its tunneling, it uses its sharp claws to shatter them and then carries on digging.'),
  ('national', 28, 10204, false, '날카로운 발톱으로 찍으며 나무에 오른다. 아래에서 기다리는 모래두지들에게 나무열매를 떨어뜨려 나눠준다.', 'It climbs trees by hooking on with its sharp claws. Sandslash shares the berries it gathers, dropping them down to Sandshrew waiting below the tree.'),
  ('national', 37, 10205, false, '6개의 꼬리는 자라면서 털의 결이 좋아지며 아름다워진다. 안으면 살짝 따듯하다.', 'In its belly burns a fire, which Vulpix spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.'),
  ('national', 38, 10206, false, '머리가 좋고 집념이 강하다. 장난으로 꼬리를 잡으면 1000년 동안 화를 입는다고 한다.', 'The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.'),
  ('national', 50, 10207, false, '얕은 땅속을 이동한다. 굴을 파며 다닌 곳은 지면이 솟아 있기 때문에 바로 알 수 있다.', 'It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.'),
  ('national', 51, 10208, false, '지하 100km까지 파고들 수 있는 파워를 간직한 세쌍둥이 디그다. 땅 밑은 아무도 모른다.', 'These Diglett triplets dig over 60 miles below sea level. No one knows what it’s like underground.'),
  ('national', 52, 10209, false, '이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.', 'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.'),
  ('national', 53, 10210, false, '움직임은 우아하고 품위 있다. 야만스러운 나이킹과는 잘 맞지 않아 서로를 멸시한다.', 'Its elegant and refined behavior clashes with that of the barbaric Perrserker. The relationship between the two is one of mutual disdain.'),
  ('national', 74, 10211, false, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
  ('national', 75, 10212, false, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
  ('national', 76, 10213, false, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
  ('national', 88, 10214, false, '진흙이 뭉쳐져서 태어났다. 악취 때문에 건드릴 엄두가 안 나고 지나간 자리에는 풀 한 포기 나지 않는다.', 'Made of congealed sludge. It smells too putrid to touch. Even weeds won’t grow in its path.'),
  ('national', 89, 10215, false, '악취가 심하다! 기절할 정도로 강렬하지만 질뻐기는 코가 퇴화해서 냄새를 맡지 못한다.', 'Smells so awful, it can cause fainting. Through degeneration of its nose, it lost its sense of smell.'),
  ('national', 103, 10216, false, '3개의 머리가 똘똘 뭉쳐서 쏘는 사이코 파워는 강력하다. 날씨가 흐리면 움직임이 둔하다.', 'When they work together, Exeggutor’s three heads can put out powerful psychic energy. Cloudy days make this Pokémon sluggish.'),
  ('national', 105, 10217, false, '진화로 인해 쓰고 있던 어미의 뼈는 일체화되었고 성격은 더욱 난폭해졌다.', 'When this Pokémon evolved, the skull of its mother fused to it. Marowak’s temperament also turned vicious at the same time.'),
  ('national', 658, 10219, false, '닌자처럼 신출귀몰하다. 재빠른 움직임으로 상대를 농락하면서 물의 수리검으로 벤다.', 'It appears and vanishes with a ninja’s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
  ('national', 718, 10222, false, '생태계를 위협하는 자와 싸울 때 더욱 강력한 모습으로 변화한다고 전해진다.', 'Some say it can change to an even more powerful form when battling those who threaten the ecosystem.'),
  ('national', 718, 10340, false, '생태계를 위협하는 자와 싸울 때 더욱 강력한 모습으로 변화한다고 전해진다.', 'Some say it can change to an even more powerful form when battling those who threaten the ecosystem.'),
  ('national', 722, 722, true, '낮 동안에는 광합성으로 힘을 비축하고 밤이 되면 소리 없이 날며 먹이를 찾는다.', 'Flies noiselessly on delicate wings. It has mastered the art of deftly launching dagger-sharp feathers from those same wings.'),
  ('national', 723, 723, true, '날개 손질을 게을리하지 않는다. 몸가짐을 정돈하는 이유뿐만 아니라 칼날깃의 날을 유지하기 위해서다.', 'Regularly basks in sunlight to gather power—presumably due to the frigid climate. Nonetheless, the edges of the blade quills set into its wings are keen as ever.'),
  ('national', 724, 724, true, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('national', 725, 725, true, '냐오불에게 신뢰받기 전에 쓰다듬으려고 하면 날카로운 발톱으로 심하게 할퀴니 주의가 필요하다.', 'Trying to pet Litten before it trusts you will result in a nasty scratch from its sharp claws. Be careful.'),
  ('national', 726, 726, true, '강적을 상대하게 되면 전투 의욕이 높아지고 동시에 불꽃 방울의 화력도 올라간다.', 'When facing a powerful enemy, Torracat’s fighting spirit gets pumped up, and its fire bell blazes hotter.'),
  ('national', 727, 727, true, '난폭한 거동이 눈에 띄지만 작은 포켓몬을 도와주는 상냥한 일면도 있다.', 'Incineroar’s rough and aggressive behavior is its most notable trait, but the way it helps out small Pokémon shows that it has a kind side as well.'),
  ('national', 728, 728, true, '매일 열심히 연습하면 결국에는 커다랗고 성능 좋은 벌룬을 만들 수 있게 된다.', 'If Popplio want to create big, powerful balloons, they must be persistent. It takes daily practice for these Pokémon to develop their skills.'),
  ('national', 729, 729, true, '파도가 잔잔한 밤이 되면 리더인 누리레느의 노랫소리에 맞춰 동료와 함께 춤을 춘다.', 'On nights when the sea is calm, Brionne dance with one another to the singing of the Primarina that’s leading them.'),
  ('national', 730, 730, true, '싸움은 누리레느의 스테이지다. 노래와 벌룬이 흩날리는 모습은 보는 이들을 매료시킨다.', 'For Primarina, every battle’s a stage. Its singing and the dancing of its balloons will mesmerize the audience.'),
  ('national', 731, 731, true, '가늘어 보이지만 강인한 목 근육을 가졌다. 초당 16연타로 나무를 마구 쪼아 댄다.', 'It may look spindly, but its neck muscles are heavy-duty. It can peck at a tree 16 times per second!'),
  ('national', 732, 732, true, '먹은 나무열매의 씨를 부리에서 발사한다. 씨는 대지에 흩어져서 새로운 풀과 나무가 자라난다.', 'From its mouth, it fires the seeds of berries it has eaten. The scattered seeds give rise to new plants.'),
  ('national', 733, 733, true, '암수의 사이가 좋다고 알려져 있다. 행운을 부르기 위해 결혼식에 데리고 온다.', 'Known for forming harmonious couples, this Pokémon is brought to wedding ceremonies as a good luck charm.'),
  ('national', 734, 734, true, '무엇이든 먹지만 신선하고 살아 있는 것을 좋아해서 먹이를 찾아 길을 누비고 다닌다.', 'Although it will eat anything, it prefers fresh living things, so it marches down streets in search of prey.'),
  ('national', 735, 735, true, '매우 인내심이 강한 성질이지만 좋아하는 꼬렛을 발견하면 이성을 잃고 덤벼든다.', 'Patient by nature, this Pokémon loses control of itself and pounces when it spots its favorite meal—Rattata!'),
  ('national', 736, 736, true, '커다란 턱으로 숲에서 땅을 파고 굴을 만든다. 달콤한 수액을 매우 좋아한다.', 'It uses its big jaws to dig nests into the forest floor, and it loves to feed on sweet tree sap.'),
  ('national', 737, 737, true, '먹은 낙엽을 소화할 때 전기가 발생하는 구조로 되어 있다. 배의 전기 주머니에 충전된다.', 'Its digestive processes convert the leaves it eats into electricity. An electric sac in its belly stores the electricity for later use.'),
  ('national', 738, 738, true, '예비 배터리로서 전지충이를 안고 날면 높은 전력의 전자빔을 연사할 수 있다.', 'If it carries a Charjabug to use as a spare battery, a flying Vikavolt can rapidly fire high-powered beams of electricity.'),
  ('national', 739, 739, true, '야자나무로 착각하고 나시에 오르는 일도 있다. 분노를 사 내동댕이쳐진 다음 짓밟힌다.', 'Crabrawler has been known to mistake Exeggutor for a coconut tree and climb it. The enraged Exeggutor shakes it off and stomps it.'),
  ('national', 740, 740, true, '생각하기보다는 일단 때리고 본다. 눈사태를 펀치 러시로 되받아쳤다는 기록도 있다.', 'Before it stops to think, it just starts pummeling. There are records of its turning back avalanches with a flurry of punches.'),
  ('national', 741, 741, true, '다홍꿀을 빨아들인 춤추새. 트레이너가 틀린 지시를 내리면 격렬하게 화를 내는 격정적인 성격이다.', 'This Oricorio has drunk red nectar. If its Trainer gives the wrong order, this passionate Pokémon becomes fiercely angry.'),
  ('national', 741, 10225, false, '다홍꿀을 빨아들인 춤추새. 트레이너가 틀린 지시를 내리면 격렬하게 화를 내는 격정적인 성격이다.', 'This Oricorio has drunk red nectar. If its Trainer gives the wrong order, this passionate Pokémon becomes fiercely angry.'),
  ('national', 741, 10226, false, '다홍꿀을 빨아들인 춤추새. 트레이너가 틀린 지시를 내리면 격렬하게 화를 내는 격정적인 성격이다.', 'This Oricorio has drunk red nectar. If its Trainer gives the wrong order, this passionate Pokémon becomes fiercely angry.'),
  ('national', 741, 10227, false, '다홍꿀을 빨아들인 춤추새. 트레이너가 틀린 지시를 내리면 격렬하게 화를 내는 격정적인 성격이다.', 'This Oricorio has drunk red nectar. If its Trainer gives the wrong order, this passionate Pokémon becomes fiercely angry.'),
  ('national', 742, 742, true, '상대가 내뿜는 오라로 다음 행동을 예측한다. 공격을 가볍게 피하고 반격한다.', 'An opponent’s aura can tell Cutiefly what that opponent’s next move will be. Then Cutiefly can glide around the attack and strike back.'),
  ('national', 743, 743, true, '비에 젖는 것을 매우 싫어한다. 흐린 날이 많은 가라르지방에서는 모습을 좀처럼 보기 힘들다.', 'Ribombee absolutely hate getting wet or rained on. In the cloudy Galar region, they are very seldom seen.'),
  ('national', 744, 744, true, '목의 바위를 땅에 세게 부딪쳐서 상대를 위협한다. 풀이 죽은 순간에 덮친다.', 'This Pokémon intimidates opponents by striking the ground with the rocks on its neck. The moment an opponent flinches, Rockruff attacks.'),
  ('national', 744, 10310, false, '목의 바위를 땅에 세게 부딪쳐서 상대를 위협한다. 풀이 죽은 순간에 덮친다.', 'This Pokémon intimidates opponents by striking the ground with the rocks on its neck. The moment an opponent flinches, Rockruff attacks.'),
  ('national', 745, 745, true, '빠른 움직임으로 먹이를 차츰차츰 궁지에 몰아넣는다. 이빨은 항상 급소를 노리고 있다.', 'With swift movements, this Pokémon gradually backs its prey into a corner. Lycanroc’s fangs are always aimed toward opponents’ weak spots.'),
  ('national', 745, 10228, false, '빠른 움직임으로 먹이를 차츰차츰 궁지에 몰아넣는다. 이빨은 항상 급소를 노리고 있다.', 'With swift movements, this Pokémon gradually backs its prey into a corner. Lycanroc’s fangs are always aimed toward opponents’ weak spots.'),
  ('national', 745, 10311, false, '빠른 움직임으로 먹이를 차츰차츰 궁지에 몰아넣는다. 이빨은 항상 급소를 노리고 있다.', 'With swift movements, this Pokémon gradually backs its prey into a corner. Lycanroc’s fangs are always aimed toward opponents’ weak spots.'),
  ('national', 746, 746, true, '위험을 느끼면 눈물을 글썽인다. 눈물의 빛은 그들만의 신호로 신호를 받고 많은 동료가 모인다.', 'When it senses danger, its eyes tear up. The sparkle of its tears signals other Wishiwashi to gather.'),
  ('national', 746, 10229, false, '위험을 느끼면 눈물을 글썽인다. 눈물의 빛은 그들만의 신호로 신호를 받고 많은 동료가 모인다.', 'When it senses danger, its eyes tear up. The sparkle of its tears signals other Wishiwashi to gather.'),
  ('national', 747, 747, true, '알로라지방의 시마사리와 달리 가라르의 시마사리는 코산호의 가지의 맛을 아직 모른다.', 'Unlike their Alolan counterparts, the Mareanie of the Galar region have not yet figured out that the branches of Corsola are delicious.'),
  ('national', 748, 748, true, '고래왕도 사흘 밤낮 괴로워할 정도의 맹독을 체내 독주머니에 듬뿍 비축하고 있다.', 'Within the poison sac in its body is a poison so toxic that Pokémon as large as Wailord will still be suffering three days after it first takes effect.'),
  ('national', 749, 749, true, '흙을 먹어서 만든 진흙을 다리에 바르면 험한 길에서도 미끄러지지 않고 걸을 수 있게 된다.', 'It eats dirt to create mud and smears this mud all over its feet, giving them the grip needed to walk on rough terrain without slipping.'),
  ('national', 750, 750, true, '10톤이 넘는 짐을 끌고 자지도 쉬지도 않고 가라르지방을 종단할 수 있는 지구력이 있다.', 'Mudsdale has so much stamina that it could carry over 10 tons across the Galar region without rest or sleep.'),
  ('national', 751, 751, true, '평소에는 물속에서 생활하지만 먹이를 찾으러 육지로 올라올 때는 수포를 뒤집어쓴다.', 'Dewpider normally lives underwater. When it comes onto land in search of food, it takes water with it in the form of a bubble on its head.'),
  ('national', 752, 752, true, '머리의 수포 안에 물거미를 넣어 남은 먹이를 먹이면서 돌봐준다.', 'It acts as a caretaker for Dewpider, putting them inside its bubble and letting them eat any leftover food.'),
  ('national', 753, 753, true, '낮에는 햇빛을 받으며 새근새근 잔다. 한밤중에 잠에서 깨어 활동을 시작한다.', 'During the day, Fomantis basks in sunlight and sleeps peacefully. It wakes and moves around at night.'),
  ('national', 754, 754, true, '양팔의 꽃잎은 얇고 예리하다. 빛을 모아 빔을 쏘기도 한다.', 'The petals on this Pokémon’s arms are thin and super sharp, and they can fire laser beams if Lurantis gathers light first.'),
  ('national', 755, 755, true, '낮에도 어두운 숲에서 생활한다. 점멸하면서 빛나는 포자를 흩뿌려 적을 잠들게 한다.', 'Morelull live in forests that stay dark even during the day. They scatter flickering spores that put enemies to sleep.'),
  ('national', 756, 756, true, '한밤중에 숲속에서 빛을 발견하더라도 다가가면 안 된다. 마셰이드가 잠들어 버리게 한다.', 'If you see a light deep in a forest at night, don’t go near. Shiinotic will make you fall fast asleep.'),
  ('national', 757, 757, true, '먹이의 뒤로 숨어들어서 눈치채기 전에 독가스를 퍼부어 움직이지 못하게 한다.', 'This sneaky Pokémon will slink behind its prey and immobilize it with poisonous gas before the prey even realizes Salandit is there.'),
  ('national', 758, 758, true, '염뉴트들의 싸움은 거느리고 있는 수컷 야도뇽의 수로 승패가 정해지는 듯하다.', 'The winner of competitions between Salazzle is decided by which one has the most male Salandit with it.'),
  ('national', 759, 759, true, '앞발을 바둥바둥 흔들어 몸을 지키는 모습은 귀엽지만 큰 나무도 꺾을 정도의 위력이 있다.', 'The way it protects itself by flailing its arms may be an adorable sight, but stay well away. This is flailing that can snap thick tree trunks.'),
  ('national', 760, 760, true, '격투가가 무색할 정도의 기술로 먹이를 잡아 양쪽 겨드랑이에 끼우고 거처로 갖고 간다.', 'The moves it uses to take down its prey would make a martial artist jealous. It tucks subdued prey under its arms to carry them to its nest.'),
  ('national', 761, 761, true, '습격당할 때 흘리는 땀은 달콤하고 맛있다. 그 향기가 적을 더 늘리고 만다.', 'When under attack, it secretes a sweet and delicious sweat. The scent only calls more enemies to it.'),
  ('national', 762, 762, true, '쪼아대는 파크로우를 머리의 꼭지로 후려치고 예리한 발차기를 먹인다.', 'Any Corvisquire that pecks at this Pokémon will be greeted with a smack from its sepals followed by a sharp kick.'),
  ('national', 763, 763, true, '단단하고 뾰족한 발끝으로 킥을 먹여서 상대의 몸과 마음에 지워지지 않는 상처를 남긴다.', 'A kick from the hardened tips of this Pokémon’s legs leaves a wound in the opponent’s body and soul that will never heal.'),
  ('national', 764, 764, true, '매우 좋은 향기가 나는 포켓몬이다. 몸에 붙이는 꽃이 달라서 큐아링마다 향이 다르다', 'These Pokémon smell very nice. All Comfey wear different flowers, so each of these Pokémon has its own individual scent.'),
  ('national', 765, 765, true, '숲 구석구석까지 파악하고 있어 상처 입은 포켓몬이 있으면 약초를 찾아 치료한다.', 'It knows the forest inside and out. If it comes across a wounded Pokémon, Oranguru will gather medicinal herbs to treat it.'),
  ('national', 766, 766, true, '20마리 정도가 무리 지어 생활한다. 정해진 역할을 해내면서 혹독한 자연에서 꿋꿋하게 살아남았다.', 'Passimian live in groups of about 20, with each member performing an assigned role. Through cooperation, the group survives.'),
  ('national', 767, 767, true, '무리가 모여 다니며 항상 주위를 경계한다. 적의 기척을 느끼면 뿔뿔이 흩어져 도망간다.', 'Wimpod gather in swarms, constantly on the lookout for danger. They scatter the moment they detect an enemy’s presence.'),
  ('national', 768, 768, true, '해저의 굴이나 침몰선이 거처다. 케오퍼스와 싸워서 진 쪽이 먹이가 된다.', 'They live in sunken ships or in holes in the seabed. When Golisopod and Grapploct battle, the loser becomes the winner’s meal.'),
  ('national', 769, 769, true, '주로 모래사장에 산다. 입안에 손을 넣은 상대를 조종하여 자신을 크게 만든다.', 'Sandygast mainly inhabits beaches. It takes control of anyone who puts their hand into its mouth, forcing them to make its body bigger.'),
  ('national', 770, 770, true, '해변에 살지만 물을 싫어한다. 세찬 비를 맞으면 성의 형태를 유지하지 못한다.', 'This Pokémon lives on beaches, but it hates water. Palossand can’t maintain its castle-like shape if it gets drenched by a heavy rain.'),
  ('national', 771, 771, true, '보습 효과가 뛰어난 점액이 피부를 감싸고 있어 며칠을 육지에 있어도 마르지 않는다.', 'It’s covered in a slime that keeps its skin moist, allowing it to stay on land for days without drying up.'),
  ('national', 772, 772, true, '신화 속 포켓몬을 모델로 만들었지만 힘이 폭주하는 것을 억제하는 마스크를 쓰고 있다.', 'It was modeled after a mighty Pokémon of myth. The mask placed upon it limits its power in order to keep it under control.'),
  ('national', 773, 773, true, '본래의 힘을 해방하게 하는 마지막 요소는 신뢰하는 트레이너와의 유대였다.', 'The final factor needed to release this Pokémon’s true power was a strong bond with a Trainer it trusts.'),
  ('national', 773, 10232, false, '본래의 힘을 해방하게 하는 마지막 요소는 신뢰하는 트레이너와의 유대였다.', 'The final factor needed to release this Pokémon’s true power was a strong bond with a Trainer it trusts.'),
